import{_ as r,o as d,c as a,a2 as e}from"./chunks/framework.G0y0PQA7.js";const o="/relio/shots/ko/file-new-dialog.png",l="/relio/shots/ko/file-recent-menu.png",k=JSON.parse('{"title":"파일","description":"","frontmatter":{},"headers":[],"relativePath":"features/file.md","filePath":"features/file.md"}'),i={name:"features/file.md"};function s(n,t,h,b,g,u){return d(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="파일" tabindex="-1">파일 <a class="header-anchor" href="#파일" aria-label="Permalink to &quot;파일&quot;">​</a></h1><p>새로 만들기·열기·저장, 최근 파일, 문서 탭, 자동 백업과 복구처럼 파일 메뉴와 문서 탭에서 하는 일을 설명합니다.</p><p>처음이라면 빠른 시작의 <a href="/relio/quick/start">처음 시작하기</a>와 <a href="/relio/quick/from-ermaster">ERMaster에서 넘어오기</a>를 먼저 보세요.</p><h2 id="파일-메뉴" tabindex="-1">파일 메뉴 <a class="header-anchor" href="#파일-메뉴" aria-label="Permalink to &quot;파일 메뉴&quot;">​</a></h2><table tabindex="0"><thead><tr><th>메뉴 › 항목</th><th>단축키</th><th>하는 일</th></tr></thead><tbody><tr><td>파일 › 새 다이어그램</td><td><kbd>Ctrl</kbd>+<kbd>N</kbd></td><td>DB 종류와 대상 버전을 골라 빈 문서를 엽니다.</td></tr><tr><td>파일 › 열기…</td><td><kbd>Ctrl</kbd>+<kbd>O</kbd></td><td><code>.erm</code> 파일을 엽니다.</td></tr><tr><td>파일 › 최근 파일 ▸</td><td></td><td>최근에 연 파일 목록. 맨 아래 <strong>목록 지우기</strong>로 비웁니다.</td></tr><tr><td>파일 › 닫기</td><td><kbd>Ctrl</kbd>+<kbd>W</kbd></td><td>지금 문서 탭을 닫습니다.</td></tr><tr><td>파일 › 저장</td><td><kbd>Ctrl</kbd>+<kbd>S</kbd></td><td>지금 문서를 저장합니다.</td></tr><tr><td>파일 › 다른 이름으로 저장…</td><td><kbd>Ctrl</kbd>+<kbd>Shift</kbd>+<kbd>S</kbd></td><td>새 위치·이름으로 저장합니다.</td></tr><tr><td>파일 › 정렬해 다시 저장</td><td></td><td>바뀐 것이 없어도 Git에 맞춘 순서로 다시 저장합니다. 아래 &quot;정렬해 저장&quot;을 보세요.</td></tr><tr><td>파일 › 비교·병합 ▸</td><td></td><td>두 모델 비교와 합치기. <a href="/relio/features/git">Git과 합치기</a>에서 설명합니다.</td></tr><tr><td>파일 › Git 이력</td><td></td><td>이 파일의 Git 이력 패널을 열고 닫습니다. <a href="/relio/features/git">Git과 합치기</a></td></tr><tr><td>파일 › 가져오기 ▸</td><td></td><td>DB에서…, 파일에서…, SQL·DBML·Mermaid·Markdown에서… — <a href="/relio/features/import">가져오기와 다른 형식</a>·<a href="/relio/features/database">DB 연동</a></td></tr><tr><td>파일 › 내보내기 ▸</td><td></td><td>DDL…부터 모델 JSON…까지 — <a href="/relio/features/ddl">DDL</a>·<a href="/relio/features/export">내보내기</a></td></tr><tr><td>파일 › DB로 내보내기…</td><td></td><td>모델을 DB에 바로 만듭니다. <a href="/relio/features/database">DB 연동</a></td></tr><tr><td>파일 › 페이지 설정… · 인쇄…</td><td><kbd>Ctrl</kbd>+<kbd>P</kbd>(인쇄)</td><td><a href="/relio/features/export#인쇄">내보내기 › 인쇄</a></td></tr><tr><td>파일 › 끝내기</td><td></td><td>Relio를 닫습니다. 저장하지 않은 문서가 있으면 <strong>저장하고 끝내기</strong> · <strong>저장하지 않고 끝내기</strong>를 묻습니다.</td></tr></tbody></table><h2 id="새로-만들기" tabindex="-1">새로 만들기 <a class="header-anchor" href="#새로-만들기" aria-label="Permalink to &quot;새로 만들기&quot;">​</a></h2><p>파일 › 새 다이어그램(<kbd>Ctrl</kbd>+<kbd>N</kbd>)을 누르면 새 다이어그램 창이 열립니다.</p><ul><li><strong>데이터베이스</strong> — 지원 DB 12가지 가운데 하나를 고릅니다. MySQL을 고르면 <strong>대상 제품</strong>(MySQL·MariaDB)도 고릅니다.</li><li><strong>대상 버전</strong> — 실제로 쓸 DB 버전입니다. 고르지 않으면 &quot;버전 미지정&quot;이 되어 그 DB의 가장 낮은 지원 버전(예: PostgreSQL 9.4)부터 되는 문법을 기준으로 설계를 검사하고 DDL을 만듭니다. 모르면 그대로 두세요.</li><li><strong>만들기</strong>를 누르면 이름 없는 새 탭이 열립니다. 위치와 이름은 처음 저장할 때 정합니다.</li></ul><p>대상 버전은 <code>.erm</code> 파일 안이 아니라 이 PC에 파일마다 기억합니다. 다른 PC에서 열면 다시 고릅니다. 나중에 바꾸려면 상태 표시줄 맨 왼쪽(예: &quot;PostgreSQL 16&quot;)을 눌러 옵션 창의 데이터베이스 탭을 엽니다.</p><figure class="shot" data-scene="file-new-dialog"><img src="'+o+'" alt="새 다이어그램 창 — 데이터베이스와 대상 버전 고르기" loading="lazy"><figcaption>새 다이어그램 창 — 데이터베이스와 대상 버전 고르기</figcaption></figure><h2 id="열기" tabindex="-1">열기 <a class="header-anchor" href="#열기" aria-label="Permalink to &quot;열기&quot;">​</a></h2><ul><li>파일 › 열기…(<kbd>Ctrl</kbd>+<kbd>O</kbd>)로 고르거나, <code>.erm</code> 파일을 창에 끌어다 놓습니다. 여러 파일은 탭으로 하나씩 열립니다.</li><li>이미 열려 있는 파일을 다시 열면 그 탭으로 갑니다.</li><li><code>.sql</code>·<code>.ddl</code>·<code>.dbml</code>·<code>.mmd</code>·<code>.mermaid</code>·<code>.md</code> 파일을 열거나 끌어다 놓으면 바로 넣지 않고 <a href="/relio/features/import">가져오기 창</a>이 열립니다. 가져오기는 파일 하나씩 합니다.</li><li><strong>샘플 열기</strong> — 시작 화면이나 도움말 › 샘플 열기 ▸에서 <strong>PostgreSQL — 온라인 서점</strong>(테이블 19개)·<strong>MySQL — 회원·권한 관리</strong>(테이블 16개)를 고릅니다. 앱에 들어 있어 인터넷 없이 열리고, 이름 없는 새 문서(사본)로 열리므로 고쳐도 샘플은 그대로입니다. 저장하면 다른 이름으로 저장 창이 뜹니다.</li></ul><h3 id="고쳐서-열기" tabindex="-1">고쳐서 열기 <a class="header-anchor" href="#고쳐서-열기" aria-label="Permalink to &quot;고쳐서 열기&quot;">​</a></h3><p>망가진 파일은 고칠 수 있는 데까지 고쳐서 엽니다. 그때 &quot;손상된 부분을 복구해 열었습니다&quot; 창에 <strong>위치 · 항목 · 원래 값 · 해석한 값</strong>이 표로 나오고, 같은 내용이 문제 목록에도 남습니다. 꼭 살펴봐야 할 항목은 &quot;확인 필요&quot;로 위에 노랗게 표시됩니다. <strong>목록 복사</strong>로 표를 복사할 수 있습니다. 저장하면 고친 내용으로 저장됩니다.</p><p>Git 병합 충돌 표시(<code>&lt;&lt;&lt;&lt;&lt;&lt;&lt;</code>)가 남은 파일은 그대로 열 수 없습니다. 안내 창의 **Git 병합 충돌 풀기…**로 바로 풉니다. <a href="/relio/features/git#합치기">Git과 합치기</a>를 보세요.</p><h2 id="최근-파일" tabindex="-1">최근 파일 <a class="header-anchor" href="#최근-파일" aria-label="Permalink to &quot;최근 파일&quot;">​</a></h2><p>파일 › 최근 파일 ▸에 파일 이름과 폴더가 보입니다. 앞의 아홉 개에는 번호가 붙습니다. 그사이 없어진 파일은 흐리게 보이고 열 수 없습니다. 맨 아래 <strong>목록 지우기</strong>로 목록을 비웁니다. 시작 화면의 최근 파일 목록에서는 항목마다 <strong>목록에서 빼기</strong>로 하나씩 뺄 수 있습니다.</p><figure class="shot" data-scene="file-recent-menu"><img src="'+l+'" alt="파일 › 최근 파일 하위 메뉴 — 파일 이름과 폴더, 목록 지우기" loading="lazy"><figcaption>파일 › 최근 파일 하위 메뉴 — 파일 이름과 폴더, 목록 지우기</figcaption></figure><h2 id="저장" tabindex="-1">저장 <a class="header-anchor" href="#저장" aria-label="Permalink to &quot;저장&quot;">​</a></h2><ul><li><strong>저장</strong>(<kbd>Ctrl</kbd>+<kbd>S</kbd>)은 바뀐 것이 있을 때 씁니다. 한 번도 저장하지 않은 새 문서·샘플 사본은 다른 이름으로 저장 창이 뜹니다.</li><li>저장은 임시 파일에 다 쓴 뒤 원래 파일과 바꿔 넣습니다. 저장 중에 꺼져도 원래 파일이 깨지지 않습니다.</li><li>바뀐 문서는 문서 탭 이름 앞에 <code>*</code>가 붙습니다.</li><li>문서를 닫을 때 저장하지 않은 변경이 있으면 <strong>저장</strong> · <strong>저장 안 함</strong> · <strong>취소</strong>를 묻습니다.</li></ul><h3 id="저장할-때-바깥-변경을-만나면" tabindex="-1">저장할 때 바깥 변경을 만나면 <a class="header-anchor" href="#저장할-때-바깥-변경을-만나면" aria-label="Permalink to &quot;저장할 때 바깥 변경을 만나면&quot;">​</a></h3><p>마지막으로 열거나 저장한 뒤 다른 프로그램이나 다른 사람이 파일을 바꿨으면, 저장 직전에 &quot;저장하려는 파일이 바깥에서 바뀌었습니다&quot; 창이 뜹니다.</p><table tabindex="0"><thead><tr><th>단추</th><th>하는 일</th></tr></thead><tbody><tr><td>합치기…</td><td>내 변경과 바깥 변경을 모델 단위로 합치는 합치기 탭을 엽니다.</td></tr><tr><td>차이 보기</td><td>저장을 멈추고 바깥 파일과 내 문서를 비교 탭으로 엽니다. 다시 저장하면 또 묻습니다.</td></tr><tr><td>덮어쓰기 (바깥 변경 버림)</td><td>바깥 변경을 버리고 내 문서로 덮어씁니다. 덮어쓰기 전 파일은 자동 백업 폴더에 남겨 둡니다.</td></tr><tr><td>다른 이름으로 저장…</td><td>다른 파일로 저장합니다.</td></tr><tr><td>취소</td><td>저장하지 않습니다.</td></tr></tbody></table><p>파일이 지워졌거나 옮겨졌으면 &quot;저장하려는 파일이 없어졌습니다&quot; 창에서 <strong>이 위치에 다시 저장</strong>을 고를 수 있습니다.</p><h3 id="창으로-돌아왔을-때" tabindex="-1">창으로 돌아왔을 때 <a class="header-anchor" href="#창으로-돌아왔을-때" aria-label="Permalink to &quot;창으로 돌아왔을 때&quot;">​</a></h3><p>열어 둔 파일을 바깥에서 바꾸면 창으로 돌아올 때 &quot;다른 프로그램이 파일을 바꿨습니다&quot; 창이 뜹니다. 저장하지 않은 변경이 없으면 <strong>다시 읽기</strong> · <strong>그대로 두기</strong>를, 있으면 <strong>합치기…</strong> · <strong>다시 읽기 (내 변경 버림)</strong> · <strong>내 변경 유지</strong>를 고릅니다. 열어 둔 파일이 지워졌으면 &quot;파일이 없어졌습니다&quot;를 알리고 문서는 그대로 둡니다. 저장하면 그 위치에 다시 만듭니다.</p><h3 id="정렬해-저장" tabindex="-1">정렬해 저장 <a class="header-anchor" href="#정렬해-저장" aria-label="Permalink to &quot;정렬해 저장&quot;">​</a></h3><p>도구 › 환경 설정 › 일반의 <strong>Git에 맞춰 정렬해 저장</strong>이 켜져 있으면(기본) 목록 순서를 고정해 저장합니다. Git 차이가 작아지고 ERMaster에서도 그대로 열립니다. 이 설정을 처음 켠 파일은 첫 저장에서 줄이 많이 바뀔 수 있으니, 파일 › 정렬해 다시 저장으로 정리만 따로 저장해 커밋해 두면 다음 변경을 검토하기 쉽습니다.</p><h2 id="문서-탭" tabindex="-1">문서 탭 <a class="header-anchor" href="#문서-탭" aria-label="Permalink to &quot;문서 탭&quot;">​</a></h2><ul><li>열린 파일마다 탭이 하나 생깁니다. 끌어서 순서를 바꿉니다.</li><li><kbd>Ctrl</kbd>+<kbd>Tab</kbd> / <kbd>Ctrl</kbd>+<kbd>Shift</kbd>+<kbd>Tab</kbd>로 다음·이전 탭으로 갑니다.</li><li>탭을 마우스 가운데 버튼으로 누르면 닫힙니다.</li><li>탭을 오른쪽 클릭하면 <strong>닫기</strong> · <strong>다른 탭 닫기</strong> · <strong>모두 닫기</strong> · <strong>경로 복사</strong> · <strong>폴더에서 열기</strong>가 있습니다.</li><li>탭을 더블클릭하면 오른쪽·아래 패널을 한 번에 접어 캔버스를 넓게 봅니다. <a href="/relio/features/canvas#패널과-시작-화면">캔버스와 팔레트</a></li></ul><h2 id="껐다-켜면" tabindex="-1">껐다 켜면 <a class="header-anchor" href="#껐다-켜면" aria-label="Permalink to &quot;껐다 켜면&quot;">​</a></h2><p>끌 때 열려 있던 파일을 같은 탭 순서로 다시 열고, 보던 탭을 앞에 둡니다. 그사이 없어진 파일은 건너뛰고, 하나도 없으면 시작 화면이 나옵니다. 원하지 않으면 도구 › 환경 설정 › 일반에서 <strong>시작할 때 마지막에 열려 있던 문서 다시 열기</strong>를 끕니다.</p><h2 id="자동-백업과-복구" tabindex="-1">자동 백업과 복구 <a class="header-anchor" href="#자동-백업과-복구" aria-label="Permalink to &quot;자동 백업과 복구&quot;">​</a></h2><ul><li>저장하지 않은 변경이 있으면 정해진 간격(기본 5분)마다 설정 폴더의 <code>backup</code> 폴더에 파일마다 최근 10개를 남깁니다. 간격은 도구 › 환경 설정 › 일반의 **자동 백업 간격(분)**에서 바꾸고, 0이면 끕니다.</li><li>Relio가 정상적으로 끝나지 않았다면 다음에 시작할 때 &quot;저장하지 않은 문서 복구&quot; 창이 뜹니다. 문서 · 원래 파일 · 백업 시각을 보고 고른 뒤 <strong>복구</strong>를 누릅니다. <strong>복구하지 않음</strong>으로 넘어갈 수 있고, <strong>백업 폴더 열기</strong>로 파일을 직접 볼 수 있습니다.</li><li>복구한 문서는 &quot;변경됨&quot;으로 열립니다. 저장하면 원래 파일을 바꿉니다. 백업 파일은 그대로 남습니다.</li></ul><div class="tip custom-block"><p class="custom-block-title">팁</p><p>백업과 설정이 어디에 있는지는 <a href="/relio/features/troubleshooting#내-정보가-저장되는-곳">도움말과 문제 해결 › 내 정보가 저장되는 곳</a>에 정리해 두었습니다.</p></div>',35)])])}const f=r(i,[["render",s]]);export{k as __pageData,f as default};
